// ÉireHome Flow translations: picks the reader's language and shows every page in it.
// A classic script at the top of each page's <head>, before the stylesheet. It runs before the
// page is drawn and translates the text as the page is read in, so nothing flashes in English.
// Page scripts use it through js/core/i18n.js. How it works: specs/08-Internationalisation.md.
(function (root) {
  "use strict";

  // i18n:generated by npm run i18n from js/lib/locales.js and the files in locales/. Do not edit by hand.
  var LOCALES = [
    {"code":"en","tag":"en-IE","name":"English","status":"complete","namespaces":["account","authentication","calculator","common","contact","guide","home","journey","legal","sitemap"]},
    {"code":"pt","tag":"pt-BR","name":"Português (Brasil)","status":"complete","namespaces":["account","authentication","calculator","common","contact","guide","home","journey","legal","sitemap"]},
    {"code":"es","tag":"es-ES","name":"Español","status":"complete","namespaces":["account","authentication","calculator","common","contact","guide","home","journey","legal","sitemap"]},
    {"code":"fr","tag":"fr-FR","name":"Français","status":"complete","namespaces":["account","authentication","calculator","common","contact","guide","home","journey","legal","sitemap"]},
    {"code":"de","tag":"de-DE","name":"Deutsch","status":"complete","namespaces":["account","authentication","calculator","common","contact","guide","home","journey","legal","sitemap"]},
    {"code":"it","tag":"it-IT","name":"Italiano","status":"complete","namespaces":["account","authentication","calculator","common","contact","guide","home","journey","legal","sitemap"]},
    {"code":"pl","tag":"pl-PL","name":"Polski","status":"complete","namespaces":["account","authentication","calculator","common","contact","guide","home","journey","legal","sitemap"]},
    {"code":"ro","tag":"ro-RO","name":"Română","status":"complete","namespaces":["account","authentication","calculator","common","contact","guide","home","journey","legal","sitemap"]},
    {"code":"lt","tag":"lt-LT","name":"Lietuvių","status":"complete","namespaces":["account","authentication","calculator","common","contact","guide","home","journey","legal","sitemap"]},
  ];
  var MESSAGES_VERSION = "9f44c5005c";
  // /i18n:generated

  var SOURCE = "en";
  // Kept in the browser (all three are listed in the Privacy Policy):
  var CHOICE_KEY = "eirehome-locale";            // localStorage: the language chosen in the menu
  var PREVIEW_KEY = "eirehome-locale-preview";   // sessionStorage: a language opened with ?lang=, for this tab
  var CACHE_PREFIX = "eirehome-i18n:";           // localStorage: a copy of the texts, so the next page opens translated
  var ATTRIBUTES = ["aria-label", "placeholder", "alt", "title", "content"];
  var SELECTOR = ["[data-i18n]", "[data-i18n-html]"].concat(ATTRIBUTES.map(function (name) { return "[data-i18n-" + name + "]"; })).join(",");
  // The tags a data-i18n-html text may contain, with the attributes each one keeps.
  var ALLOWED = { A: ["href", "target", "rel", "data-keep-next"], BR: [], EM: [], STRONG: ["data-bind"], SPAN: ["class", "data-bind"] };
  var CATEGORIES = ["zero", "one", "two", "few", "many", "other"];
  var WAIT_AT_MOST = 3000; // ms the page stays hidden while its first texts download

  var active = null;       // the language shown: an entry of LOCALES
  var namespaces = ["common"];
  var store = {};          // store[code][namespace]: the texts, or their JSON until first read
  var inflight = {};
  var base = "";           // this script's address; locales/ is next to js/
  var settled = false;
  var warned = {};

  function findLocale(code) {
    for (var i = 0; i < LOCALES.length; i++) if (LOCALES[i].code === code) return LOCALES[i];
    return null;
  }

  // The language to show: one opened with ?lang= in this tab (any listed language, drafts too, for
  // reviewing), then the one chosen in the menu, then the browser's languages, then English.
  // Only complete languages are picked from the menu choice or the browser.
  function pickLocale(query, preview, choice, languages) {
    var locale = findLocale(query) || findLocale(preview);
    if (locale) return locale;
    locale = findLocale(choice);
    if (locale && locale.status === "complete") return locale;
    for (var i = 0; languages && i < languages.length; i++) {
      locale = findLocale(String(languages[i] || "").toLowerCase().split(/[-_]/)[0]);
      if (locale && locale.status === "complete") return locale;
    }
    return findLocale(SOURCE);
  }

  function read(storage, key) {
    try { return root[storage].getItem(key); } catch (err) { return null; }
  }
  function write(storage, key, value) {
    try { root[storage].setItem(key, value); return true; } catch (err) { return false; }
  }
  function remove(storage, key) {
    try { root[storage].removeItem(key); } catch (err) { /* storage blocked */ }
  }

  // Texts

  function put(code, ns, texts) { (store[code] = store[code] || {})[ns] = texts; }
  function has(code, ns) { return !!store[code] && store[code][ns] !== undefined; }

  // English is loaded on every page as the fallback but rarely read, so JSON is parsed on first use.
  function texts(code, ns) {
    var entry = store[code] && store[code][ns];
    if (typeof entry === "string") {
      try { entry = JSON.parse(entry); } catch (err) { entry = null; }
      store[code][ns] = entry;
    }
    return entry || null;
  }

  // "calculator:save.label" is the text at save.label in calculator.json. Arrays take numbers: steps.aip-0.checklist.2.
  function lookup(code, key) {
    var colon = key.indexOf(":");
    var node = colon > 0 ? texts(code, key.slice(0, colon)) : null;
    var path = key.slice(colon + 1).split(".");
    for (var i = 0; node && i < path.length; i++) node = typeof node === "object" ? node[path[i]] : undefined;
    return node === null ? undefined : node;
  }

  // A text that changes with a number: { "one": "{count} day", "other": "{count} days" }.
  function isPlural(value) {
    if (!value || typeof value !== "object" || Array.isArray(value) || typeof value.other !== "string") return false;
    for (var name in value) if (CATEGORIES.indexOf(name) < 0) return false;
    return true;
  }

  var pluralRules = {};
  function pluralCategory(tag, count) {
    try {
      if (!pluralRules[tag]) pluralRules[tag] = new Intl.PluralRules(tag);
      return pluralRules[tag].select(count);
    } catch (err) {
      return count === 1 ? "one" : "other";
    }
  }

  var numberFormats = {};
  function formatNumber(tag, n) {
    try {
      if (!numberFormats[tag]) numberFormats[tag] = new Intl.NumberFormat(tag, { maximumFractionDigits: 2 });
      return numberFormats[tag].format(n);
    } catch (err) {
      return String(n);
    }
  }

  // {name} takes params.name. Numbers are written the language's way (1,000 or 1.000).
  function interpolate(text, params, tag) {
    if (!params) return text;
    return text.replace(/\{(\w+)\}/g, function (whole, name) {
      if (!Object.prototype.hasOwnProperty.call(params, name)) return whole;
      var value = params[name];
      return typeof value === "number" ? formatNumber(tag, value) : String(value);
    });
  }

  // The text in the page's language, else in English, else null.
  function resolve(key, params) {
    var locale = active;
    var value = lookup(active.code, key);
    if (value === undefined && active.code !== SOURCE) {
      locale = findLocale(SOURCE);
      value = lookup(SOURCE, key);
    }
    if (isPlural(value)) value = value[pluralCategory(locale.tag, params ? Number(params.count) || 0 : 0)] || value.other;
    return typeof value === "string" ? interpolate(value, params, locale.tag) : null;
  }

  function t(key, params) {
    var text = resolve(key, params);
    if (text !== null) return text;
    if (settled && !warned[key]) {
      warned[key] = true;
      console.warn("No text for " + key + " in locales/en. Add it there (see specs/08-Internationalisation.md).");
    }
    return key;
  }

  // The page

  // The text for an element, once the page's language has its file for that namespace (loaded,
  // or known to be missing). Until then the English already in the HTML stays as it is.
  function elementText(key) {
    var colon = key.indexOf(":");
    return colon > 0 && has(active.code, key.slice(0, colon)) ? resolve(key, null) : null;
  }

  function translateElement(el) {
    var key = el.getAttribute("data-i18n");
    var text;
    if (key && (text = elementText(key)) !== null && el.textContent !== text) el.textContent = text;
    key = el.getAttribute("data-i18n-html");
    // Rebuilt when the text changes, or when the parser has added to the element since.
    if (key && (text = elementText(key)) !== null && (el.__i18nText !== text || el.innerHTML !== el.__i18nHtml)) setHtml(el, text);
    for (var i = 0; i < ATTRIBUTES.length; i++) {
      key = el.getAttribute("data-i18n-" + ATTRIBUTES[i]);
      if (key && (text = elementText(key)) !== null && el.getAttribute(ATTRIBUTES[i]) !== text) el.setAttribute(ATTRIBUTES[i], text);
    }
  }

  // Translates an element and everything in it: a whole page, or a document read with DOMParser.
  function translateTree(node) {
    if (node && node.nodeType === 9) node = node.documentElement;
    if (!node || node.nodeType !== 1 || !active) return;
    if (node.matches(SELECTOR)) translateElement(node);
    var found = node.querySelectorAll(SELECTOR);
    for (var i = 0; i < found.length; i++) translateElement(found[i]);
  }

  // Links may go to a page of the site, a section, an email address or a secure website.
  function safeHref(href) {
    return /^(https:\/\/|mailto:|#)/.test(href) || /^[\w-]+\.html([?#][\w=&%.:#-]*)?$/.test(href);
  }

  // Translations are part of the site, but they are still limited to a few harmless tags.
  function clean(parent) {
    var nodes = Array.prototype.slice.call(parent.childNodes);
    for (var i = 0; i < nodes.length; i++) {
      var node = nodes[i];
      if (node.nodeType === 3) continue;
      var keep = node.nodeType === 1 ? ALLOWED[node.nodeName] : null;
      if (!keep) {
        if (node.nodeType === 1) parent.replaceChild(node.ownerDocument.createTextNode(node.textContent), node);
        else parent.removeChild(node);
        continue;
      }
      for (var a = node.attributes.length - 1; a >= 0; a--) {
        var attr = node.attributes[a];
        if (keep.indexOf(attr.name) < 0 || (attr.name === "href" && !safeHref(attr.value))) node.removeAttribute(attr.name);
      }
      clean(node);
    }
  }

  function setHtml(el, html) {
    var template = document.createElement("template");
    template.innerHTML = html;
    clean(template.content);
    while (el.firstChild) el.removeChild(el.firstChild);
    el.appendChild(el.ownerDocument.importNode(template.content, true));
    el.__i18nText = html;
    el.__i18nHtml = el.innerHTML;
  }

  // Translates elements as they are added: while the page is read in, and later by the scripts.
  function watch() {
    if (!root.MutationObserver) return;
    new MutationObserver(function (records) {
      for (var r = 0; r < records.length; r++) {
        var added = records[r].addedNodes;
        for (var i = 0; i < added.length; i++) if (added[i].nodeType === 1) translateTree(added[i]);
      }
    }).observe(document.documentElement, { childList: true, subtree: true });
  }

  function hide() {
    var style = document.createElement("style");
    style.textContent = "html.i18n-pending body{visibility:hidden}";
    document.head.appendChild(style);
    document.documentElement.classList.add("i18n-pending");
  }
  function show() {
    document.documentElement.classList.remove("i18n-pending");
  }

  // Loading

  function fileUrl(code, ns) {
    return new URL("../locales/" + code + "/" + ns + ".json?v=" + MESSAGES_VERSION, base).href;
  }

  function cached(code, ns) {
    var saved = read("localStorage", CACHE_PREFIX + code + ":" + ns);
    var bar = saved ? saved.indexOf("|") : -1;
    return bar > 0 && saved.slice(0, bar) === MESSAGES_VERSION ? saved.slice(bar + 1) : null;
  }

  function loadOne(code, ns) {
    var id = code + ":" + ns;
    var locale = findLocale(code);
    if (has(code, ns)) return null;
    if (inflight[id]) return inflight[id];
    // A draft language may not have every file yet: its texts come from English meanwhile.
    if (!locale || locale.namespaces.indexOf(ns) < 0) {
      put(code, ns, null);
      return null;
    }
    var copy = cached(code, ns);
    if (copy !== null) {
      put(code, ns, copy);
      return null;
    }
    inflight[id] = fetch(fileUrl(code, ns)).then(function (res) {
      if (!res.ok) throw new Error("HTTP " + res.status);
      return res.text();
    }).then(function (body) {
      put(code, ns, JSON.parse(body));
      write("localStorage", CACHE_PREFIX + id, MESSAGES_VERSION + "|" + body);
    }).catch(function (err) {
      put(code, ns, null);
      console.error("Could not load the texts in locales/" + code + "/" + ns + ".json.", err);
    }).then(function () {
      delete inflight[id];
    });
    return inflight[id];
  }

  // Texts already copied in this browser are in place at once; the others are downloaded.
  function load(codes, list) {
    var jobs = [];
    for (var c = 0; c < codes.length; c++) {
      for (var n = 0; n < list.length; n++) {
        var job = loadOne(codes[c], list[n]);
        if (job) jobs.push(job);
      }
    }
    return Promise.all(jobs);
  }

  function languages() {
    return active.code === SOURCE ? [SOURCE] : [active.code, SOURCE];
  }

  // Once the page has loaded, copy the rest of this language's texts, so every page opens translated.
  function prefetchLater() {
    var run = function () {
      var codes = languages();
      for (var i = 0; i < codes.length; i++) load([codes[i]], findLocale(codes[i]).namespaces);
    };
    if (root.requestIdleCallback) root.requestIdleCallback(run, { timeout: 5000 });
    else setTimeout(run, 1500);
  }

  // Keeps the copies of English and of the new language, and drops the others.
  function forgetOthers(keep) {
    try {
      // Keys first: removing an item can reorder the ones left.
      var keys = [];
      for (var i = 0; i < localStorage.length; i++) keys.push(localStorage.key(i));
      for (var k = 0; k < keys.length; k++) {
        if (!keys[k] || keys[k].indexOf(CACHE_PREFIX) !== 0) continue;
        var code = keys[k].slice(CACHE_PREFIX.length).split(":")[0];
        if (code !== keep && code !== SOURCE) localStorage.removeItem(keys[k]);
      }
    } catch (err) {
      // Storage blocked: nothing was copied.
    }
  }

  // Called from the language menu. The choice is saved, and never replaced by the browser's language.
  // The new language's texts are fetched first, so the page reloads straight into it.
  function setLocale(code) {
    var locale = findLocale(code);
    if (!locale || locale.status !== "complete") return Promise.resolve(false);
    var saved = write("localStorage", CHOICE_KEY, code);
    remove("sessionStorage", PREVIEW_KEY);
    forgetOthers(code);
    return load(code === SOURCE ? [SOURCE] : [code, SOURCE], namespaces).then(function () {
      var url = new URL(location.href);
      // Storage blocked: carry the language in the address instead, for this page at least.
      if (saved) url.searchParams.delete("lang");
      else url.searchParams.set("lang", code);
      if (url.href === location.href) location.reload();
      else location.replace(url.href);
      return true;
    });
  }

  var api = {
    locales: LOCALES,
    locale: SOURCE,
    tag: "en-IE",
    ready: Promise.resolve(),
    t: t,
    has: function (key) { return resolve(key, null) !== null; },
    translate: translateTree,
    setLocale: setLocale,
    // Loads more namespaces for this page, e.g. for a part added later.
    load: function (list) { return load(languages(), list); },
    // For tests/i18n-runtime.test.js.
    _internal: { pickLocale: pickLocale, interpolate: interpolate, isPlural: isPlural, pluralCategory: pluralCategory, safeHref: safeHref },
  };

  function start() {
    var html = document.documentElement;
    base = (document.currentScript && document.currentScript.src) || location.href;
    var query = null;
    try {
      query = new URLSearchParams(location.search).get("lang");
    } catch (err) {
      // Very old browser: no ?lang=.
    }
    if (!findLocale(query)) query = null;
    if (query) write("sessionStorage", PREVIEW_KEY, query);
    var nav = root.navigator || {};
    active = pickLocale(query, read("sessionStorage", PREVIEW_KEY), read("localStorage", CHOICE_KEY),
      nav.languages && nav.languages.length ? nav.languages : [nav.language]);
    api.locale = active.code;
    api.tag = active.tag;
    html.lang = active.tag;
    html.setAttribute("data-locale", active.code);
    namespaces = (html.getAttribute("data-i18n-ns") || "common").split(/\s+/).filter(Boolean);

    var own = load([active.code], namespaces);
    api.ready = Promise.all([own, load(languages(), namespaces)]).then(function () { settled = true; });
    if (active.code !== SOURCE) {
      // The HTML is in English. Hide the page only if its texts are not in this browser yet.
      var inPlace = true;
      for (var i = 0; i < namespaces.length; i++) if (!has(active.code, namespaces[i])) inPlace = false;
      if (!inPlace) {
        hide();
        setTimeout(show, WAIT_AT_MOST);
      }
      watch();
      own.then(function () {
        translateTree(html);
        show();
      });
      // Once the whole page is read in, and before the page scripts run: a last pass over everything.
      document.addEventListener("readystatechange", function () {
        if (document.readyState === "interactive") translateTree(html);
      });
    } else {
      // English pages are written in English: only parts added later by scripts need translating.
      document.addEventListener("DOMContentLoaded", watch);
    }
    root.addEventListener("load", prefetchLater);
  }

  active = findLocale(SOURCE) || { code: SOURCE, tag: "en-IE", status: "complete", namespaces: [] };
  root.EireI18n = api;
  if (typeof document !== "undefined" && document.documentElement) {
    try {
      start();
    } catch (err) {
      // Whatever happened, the page must show: in English, as written.
      console.error("Translations could not start, so the page stays in English.", err);
      active = findLocale(SOURCE) || active;
      api.locale = active.code;
      api.tag = active.tag;
      if (document.documentElement.classList) show();
    }
  }
})(typeof window !== "undefined" ? window : globalThis);
